DROP TABLE IF EXISTS `geo_redirects`;
CREATE TABLE `geo_redirects` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `country_code` varchar(10) NOT NULL,
  `country_name` varchar(100) NOT NULL DEFAULT '',
  `redirect_url` text NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

DROP TABLE IF EXISTS `offers`;
CREATE TABLE `offers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `category` enum('microloans','credits','credit_cards','debit_cards') NOT NULL,
  `amount_min` int(11) NOT NULL DEFAULT 1000,
  `amount_max` int(11) NOT NULL DEFAULT 100000,
  `term_min_days` int(11) NOT NULL DEFAULT 1,
  `term_max_days` int(11) NOT NULL DEFAULT 365,
  `psk` decimal(6,2) NOT NULL DEFAULT 0.00,
  `rate` decimal(6,2) NOT NULL DEFAULT 0.00,
  `free_term_days` int(11) NOT NULL DEFAULT 0,
  `logo_url` text DEFAULT NULL,
  `affiliate_url` text NOT NULL,
  `borrower_category` enum('employed','unemployed','pensioner','student','self_employed','any') NOT NULL DEFAULT 'any',
  `description` text DEFAULT NULL,
  `seo_keywords` text DEFAULT NULL,
  `regions` text DEFAULT NULL,
  `rating` decimal(3,1) NOT NULL DEFAULT 0.0,
  `review_count` int(11) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO `offers` (`id`, `title`, `slug`, `category`, `amount_min`, `amount_max`, `term_min_days`, `term_max_days`, `psk`, `rate`, `free_term_days`, `logo_url`, `affiliate_url`, `borrower_category`, `description`, `seo_keywords`, `regions`, `rating`, `review_count`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('1', 'Вебзайм', 'vebzaym-1784652197596', 'microloans', '3000', '100000', '7', '100', '292.00', '0.80', '14', '/images/offer/webzaim.svg', 'https://pxl.leads.su/click/7588a80882fc0991f52f502f555fad9f?source=kosmozaim&erid=2W5zFGjNpAL', 'any', 'Процентная ставка от 0% до 0,8 % в день. 0% на 1-й заем, при условии его погашения в течение 14 дней, в ином случае 0,8% в день с 1-го дня.', '', '', '5.0', '3', '1', '3', '2026-07-21 19:43:17', '2026-07-27 11:05:31');
INSERT INTO `offers` (`id`, `title`, `slug`, `category`, `amount_min`, `amount_max`, `term_min_days`, `term_max_days`, `psk`, `rate`, `free_term_days`, `logo_url`, `affiliate_url`, `borrower_category`, `description`, `seo_keywords`, `regions`, `rating`, `review_count`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('2', 'JoyMoney', 'joymoney-1784652794306', 'microloans', '3000', '30000', '10', '14', '292.00', '0.80', '14', '/images/offer/JoyMoney.svg', 'https://pxl.leads.su/click/fef2f880e5283742cfadf801cfbbe5ce?source=kosmozaim&erid=2W5zFK1Gnqv', 'any', 'Акция для новых клиентов: для займа погашенного в срок до 14 дней начисленные проценты списываются в полном объеме, от 15 дней ставка составит 0,8% в день за весь срок пользования займом.', '', '', '5.0', '2', '1', '2', '2026-07-21 19:53:14', '2026-07-27 01:55:16');
INSERT INTO `offers` (`id`, `title`, `slug`, `category`, `amount_min`, `amount_max`, `term_min_days`, `term_max_days`, `psk`, `rate`, `free_term_days`, `logo_url`, `affiliate_url`, `borrower_category`, `description`, `seo_keywords`, `regions`, `rating`, `review_count`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('3', 'BunnyMoney', 'bunnymoney-1784653580212', 'microloans', '1000', '30000', '3', '31', '292.00', '0.80', '31', '/images/offer/BunnyMoney.svg', 'https://pxl.leads.su/click/bc564cf83b18c0e4770681c1ef45a19c?source=kosmozaim&erid=2W5zFHc6Gbz', 'any', 'Займ до 9 000 ₽ под 0% сроком от 10 до 31 дня для улучшению кредитного рейтинга при оформлении услуги «Кредитный рейтинг» за 1 699 ₽', 'займ онлайн, без подтверждения дохода, займ от 19 лет', '', '5.0', '2', '1', '1', '2026-07-21 20:06:20', '2026-07-27 10:03:07');
INSERT INTO `offers` (`id`, `title`, `slug`, `category`, `amount_min`, `amount_max`, `term_min_days`, `term_max_days`, `psk`, `rate`, `free_term_days`, `logo_url`, `affiliate_url`, `borrower_category`, `description`, `seo_keywords`, `regions`, `rating`, `review_count`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES ('4', 'Webbankir', 'webbankir-1784655589265', 'microloans', '1000', '100000', '7', '180', '292.00', '0.80', '21', '/images/offer/Webbankirl.svg', 'https://pxl.leads.su/click/34d3d8b075871048e78919226f73f86b?source=kosmozaim&erid=2W5zFHrMC2D', 'any', '0% при первичном обращении для займа суммой до 30 000 ₽ и сроком до 21 дня', 'заем за несколько минут, займ онлайн, без подтверждения дохода', '', '5.0', '3', '1', '4', '2026-07-21 20:39:49', '2026-07-27 10:15:01');

DROP TABLE IF EXISTS `reviews`;
CREATE TABLE `reviews` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `offer_id` int(11) NOT NULL,
  `author_name` varchar(100) NOT NULL,
  `rating` int(11) NOT NULL DEFAULT 5,
  `comment` text NOT NULL,
  `is_approved` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_offer_id` (`offer_id`),
  KEY `idx_approved` (`is_approved`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO `reviews` (`id`, `offer_id`, `author_name`, `rating`, `comment`, `is_approved`, `created_at`) VALUES ('3', '1', 'Владимир', '5', 'Нашёл нужную мне услугу через интернет, быстро оформил заявку. Всё прошло оперативно, получил деньги на следующий день. Очень доволен сервисом, всё работает чётко и без лишних сложностей.', '1', '2026-07-26 21:51:40');
INSERT INTO `reviews` (`id`, `offer_id`, `author_name`, `rating`, `comment`, `is_approved`, `created_at`) VALUES ('4', '2', 'Юрий', '5', 'Подруга посоветовала обратиться в микрофинансовую организацию, и я очень доволен. Оформил заём быстро, получил деньги вовремя. Отличный сервис.', '1', '2026-07-26 21:51:41');
INSERT INTO `reviews` (`id`, `offer_id`, `author_name`, `rating`, `comment`, `is_approved`, `created_at`) VALUES ('5', '2', 'Дарья', '5', 'Я очень довольна, что обратилась в эту компанию. Оформила заявку быстро, получила нужную сумму, и всё прошло без лишних хлопот. Огромное спасибо за вашу работу!', '1', '2026-07-27 01:55:16');
INSERT INTO `reviews` (`id`, `offer_id`, `author_name`, `rating`, `comment`, `is_approved`, `created_at`) VALUES ('6', '1', 'Михаил', '5', 'Я доволен сервисом «Вебзайм». Оформил заявку быстро, получил деньги оперативно. Никаких проблем не возникло, рекомендую.', '1', '2026-07-27 01:55:18');
INSERT INTO `reviews` (`id`, `offer_id`, `author_name`, `rating`, `comment`, `is_approved`, `created_at`) VALUES ('7', '4', 'Оксана', '5', 'Посоветовала мне подруга, и я оформила заявку на нужную сумму в этом сервисе. Очень довольна, получила деньги быстро и без лишних вопросов. Всё работает чётко, буду пользоваться ещё!', '1', '2026-07-27 06:02:18');
INSERT INTO `reviews` (`id`, `offer_id`, `author_name`, `rating`, `comment`, `is_approved`, `created_at`) VALUES ('8', '3', 'Полина', '5', 'Нашла через интернет удобный сервис, оформила заявку быстро и легко, получила все обещанные бонусы, очень довольна. Сервис на высшем уровне!', '1', '2026-07-27 06:02:19');
INSERT INTO `reviews` (`id`, `offer_id`, `author_name`, `rating`, `comment`, `is_approved`, `created_at`) VALUES ('9', '3', 'Юлия', '5', 'Наконец-то нашла удобный и понятный сервис для оплаты услуг! Всё оказалось просто и быстро, оформила платёж буквально за пару минут. Очень довольна результатом, теперь буду пользоваться только им. Спасибо большое за такую замечательную услугу!', '1', '2026-07-27 10:03:07');
INSERT INTO `reviews` (`id`, `offer_id`, `author_name`, `rating`, `comment`, `is_approved`, `created_at`) VALUES ('10', '4', 'Екатерина', '5', 'Очень довольна сервисом! Быстро оформила заявку, получила нужную сумму и спокойно оплатила ремонт. Сервис работает как часы, спасибо большое!', '1', '2026-07-27 10:03:07');
INSERT INTO `reviews` (`id`, `offer_id`, `author_name`, `rating`, `comment`, `is_approved`, `created_at`) VALUES ('11', '4', 'Владимир', '5', 'Оформил заём в Webbankir срочно понадобились деньги до зарплаты. Получил нужную сумму быстро, всё прошло гладко. Доволен сервисом, рекомендую.', '1', '2026-07-27 10:14:05');
INSERT INTO `reviews` (`id`, `offer_id`, `author_name`, `rating`, `comment`, `is_approved`, `created_at`) VALUES ('12', '1', 'Тимур', '5', 'Оформил заявку быстро, получил деньги вовремя, доволен сервисом. Буду рекомендовать знакомым.', '1', '2026-07-27 11:05:31');

